```ts
import type { GeospatialCamera } from "@babylonjs/lite";

const DEG_TO_RAD = Math.PI / 180;

export function centerOnLatLon(
  camera: GeospatialCamera,
  latitudeDeg: number,
  longitudeDeg: number,
): void {
  const planetRadius = camera.limits.planetRadius;
  const lat = latitudeDeg * DEG_TO_RAD;
  const lon = longitudeDeg * DEG_TO_RAD;

  // Default geospatial reference frame assumed here:
  // lat 0 / lon 0 is +Z, north is +Y, east is +X.
  // Positive longitude therefore moves toward +X.
  const cosLat = Math.cos(lat);
  const center = camera.center;

  center.x = planetRadius * cosLat * Math.sin(lon);
  center.y = planetRadius * Math.sin(lat);
  center.z = planetRadius * cosLat * Math.cos(lon);

  const { yaw, pitch, radius } = camera;
  camera._setOrientation(yaw, pitch, radius, center);
}
```

I added `src/center-on.ts` to convert latitude/longitude degrees into a surface point using the camera’s planet radius, then applied that new centre with `_setOrientation` while preserving the existing yaw, pitch, and radius. I was not certain about the exact Cartesian axis convention because the declarations do not explicitly state where lat/lon 0,0 is placed; I assumed the default frame has lat/lon 0,0 at +Z with north +Y and east +X.
